sys_script_include.script:
var MetroFareCalculator = Class.create();
MetroFareCalculator.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    getFare: function() {

        var from = this.getParameter('sysparm_from');
        var to = this.getParameter('sysparm_to');

        if (!from || !to || from == to) {
            return '0';
        }

        var AMEERPET = 'ad3fd57a83cf03d052127629feaad330';
        var MADHAPUR = 'f55fd97a83cf03d052127629feaad39a';
        var LB_NAGAR = '056f5d7a83cf03d052127629feaad34a';
        var KUKATPALLY = '43ee9d3a83cf03d052127629feaad30b';
        var JUBILEE_HILLS = 'c50f513a83cf03d052127629feaad35b';
        var PANJAGUTTA = '5e2f557a83cf03d052127629feaad367';
        var UPPAL_STADIUM = 'b54f197a83cf03d052127629feaad3de';

        var fares = {};

        function addFare(a, b, fare) {
            fares[[a, b].sort().join('_')] = fare;
        }

        addFare(AMEERPET, MADHAPUR, 30);
        addFare(AMEERPET, LB_NAGAR, 50);
        addFare(AMEERPET, KUKATPALLY, 30);
        addFare(AMEERPET, JUBILEE_HILLS, 20);
        addFare(AMEERPET, PANJAGUTTA, 20);
        addFare(AMEERPET, UPPAL_STADIUM, 60);

        addFare(MADHAPUR, LB_NAGAR, 80);
        addFare(MADHAPUR, KUKATPALLY, 40);
        addFare(MADHAPUR, JUBILEE_HILLS, 30);
        addFare(MADHAPUR, PANJAGUTTA, 30);
        addFare(MADHAPUR, UPPAL_STADIUM, 70);

        addFare(LB_NAGAR, KUKATPALLY, 60);
        addFare(LB_NAGAR, JUBILEE_HILLS, 50);
        addFare(LB_NAGAR, PANJAGUTTA, 60);
        addFare(LB_NAGAR, UPPAL_STADIUM, 40);

        addFare(KUKATPALLY, JUBILEE_HILLS, 30);
        addFare(KUKATPALLY, PANJAGUTTA, 30);
        addFare(KUKATPALLY, UPPAL_STADIUM, 70);

        addFare(JUBILEE_HILLS, PANJAGUTTA, 20);
        addFare(JUBILEE_HILLS, UPPAL_STADIUM, 60);

        addFare(PANJAGUTTA, UPPAL_STADIUM, 60);

        var key = [from, to].sort().join('_');

        return fares[key] || '0';
    },

    type: 'MetroFareCalculator'
});
